public class InfixCalculatorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object eval(String expr) {
        try {
            return InfixCalculator.evaluate(expr);
        } catch (ArithmeticException e) {
            return "ARITHMETIC";
        } catch (IllegalArgumentException e) {
            return "ILLEGAL";
        } catch (RuntimeException e) {
            return "wrong error: " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("evaluate(\"2+3*4\")", 14L, eval("2+3*4"));
        check("evaluate(\"2*3+4\")", 10L, eval("2*3+4"));
        check("evaluate(\"100/7\")", 14L, eval("100/7"));
        check("evaluate(\"10 - 2 - 3\")", 5L, eval("10 - 2 - 3"));
        check("evaluate(\"100 / 7 / 2\")", 7L, eval("100 / 7 / 2"));
        check("evaluate(\"2*3%4\")", 2L, eval("2*3%4"));
        check("evaluate(\" 7 \")", 7L, eval(" 7 "));
        check("evaluate(\"1+2*3-4/2\")", 5L, eval("1+2*3-4/2"));
        check("evaluate(\"0*5+9\")", 9L, eval("0*5+9"));
        check("evaluate(\"2-3*4\") can go negative", -10L, eval("2-3*4"));
        check("big operands stay in long", 6000000000L, eval("3000000000+3000000000"));
        check("divide by zero", "ARITHMETIC", eval("5/0"));
        check("modulo by zero", "ARITHMETIC", eval("5%0"));
        check("trailing operator", "ILLEGAL", eval("1+"));
        check("leading operator", "ILLEGAL", eval("+1"));
        check("double operator", "ILLEGAL", eval("1++2"));
        check("two numbers in a row", "ILLEGAL", eval("1 2"));
        check("bad character", "ILLEGAL", eval("1&2"));
        check("blank string", "ILLEGAL", eval("   "));
        check("null", "ILLEGAL", eval(null));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

