public class InfixCalculator {

    public static long evaluate(String expression) {
        if (expression == null) {
            throw new IllegalArgumentException("null expression");
        }
        long total = 0;
        long term = 0;
        char pendingAdditive = '+';
        char pendingMultiplicative = 0;
        boolean sawNumber = false;
        int i = 0;
        int n = expression.length();

        while (i < n) {
            char c = expression.charAt(i);
            if (c == ' ') {
                i++;
                continue;
            }
            if (c >= '0' && c <= '9') {
                if (sawNumber) {
                    throw new IllegalArgumentException("two numbers in a row");
                }
                long value = 0;
                while (i < n && expression.charAt(i) >= '0' && expression.charAt(i) <= '9') {
                    value = value * 10 + (expression.charAt(i) - '0');
                    i++;
                }
                sawNumber = true;
                if (pendingMultiplicative == '*') {
                    term = term * value;
                } else if (pendingMultiplicative == '/') {
                    if (value == 0) {
                        throw new ArithmeticException("divide by zero");
                    }
                    term = term / value;
                } else if (pendingMultiplicative == '%') {
                    if (value == 0) {
                        throw new ArithmeticException("modulo by zero");
                    }
                    term = term % value;
                } else {
                    term = value;
                }
                pendingMultiplicative = 0;
                continue;
            }
            if (c == '+' || c == '-' || c == '*' || c == '/' || c == '%') {
                if (!sawNumber) {
                    throw new IllegalArgumentException("operator without a left operand");
                }
                if (c == '+' || c == '-') {
                    total = pendingAdditive == '+' ? total + term : total - term;
                    pendingAdditive = c;
                    term = 0;
                } else {
                    pendingMultiplicative = c;
                }
                sawNumber = false;
                i++;
                continue;
            }
            throw new IllegalArgumentException("bad character: " + c);
        }

        if (!sawNumber) {
            throw new IllegalArgumentException("expression ends badly");
        }
        return pendingAdditive == '+' ? total + term : total - term;
    }
}
